#include <iostream>
#include <vector>
using namespace std;

// 1-indexed Fenwick tree over n values: point add and prefix sum in O(log n).
struct Fenwick {
    int n;
    vector<long long> tree;
    explicit Fenwick(int n) : n(n), tree(n + 1, 0) {}

    void add(int i, long long delta) {  // a[i] += delta
        for (; i <= n; i += i & -i) tree[i] += delta;
    }
    long long prefix(int i) const {  // a[1] + ... + a[i]
        long long sum = 0;
        for (; i > 0; i -= i & -i) sum += tree[i];
        return sum;
    }
    long long range(int l, int r) const {  // a[l] + ... + a[r]
        return prefix(r) - prefix(l - 1);
    }
};

int main() {
    vector<int> a = {5, 2, 9, -3, 4, 7, 1, 6};
    Fenwick fw((int)a.size());
    for (int i = 0; i < (int)a.size(); ++i) fw.add(i + 1, a[i]);

    cout << "sum a[1..7] = " << fw.prefix(7) << "\n";
    cout << "sum a[3..6] = " << fw.range(3, 6) << "\n";
    fw.add(3, 10);  // a[3]: 9 -> 19
    cout << "after a[3] += 10: sum a[3..6] = " << fw.range(3, 6) << "\n";

    // Inversions: pairs i < j with v[i] > v[j]. Values are 1..8, so index by value.
    vector<int> v = {3, 1, 4, 8, 2, 7, 6, 5};
    Fenwick seen(8);
    long long inversions = 0;
    for (int j = 0; j < (int)v.size(); ++j) {
        inversions += j - seen.prefix(v[j]);  // earlier values that are larger than v[j]
        seen.add(v[j], 1);
    }
    cout << "inversions in {3,1,4,8,2,7,6,5} = " << inversions << "\n";
    return 0;
}

#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

// Range-minimum queries on a static array: O(n log n) build, O(1) per query.
struct SparseTable {
    vector<vector<int>> st;  // st[k][i] = min of a[i .. i + 2^k - 1]
    vector<int> lg;          // lg[len] = floor(log2(len))

    explicit SparseTable(const vector<int>& a) {
        int n = (int)a.size();
        lg.assign(n + 1, 0);
        for (int len = 2; len <= n; ++len) lg[len] = lg[len / 2] + 1;
        st.assign(lg[n] + 1, vector<int>(n));
        st[0] = a;
        for (int k = 1; k <= lg[n]; ++k)
            for (int i = 0; i + (1 << k) <= n; ++i)
                st[k][i] = min(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);
    }

    int query(int l, int r) const {  // min of a[l..r], inclusive
        int k = lg[r - l + 1];
        return min(st[k][l], st[k][r - (1 << k) + 1]);
    }
};

int main() {
    vector<int> a = {7, 2, 9, 4, 6, 1, 8, 3, 5};
    SparseTable t(a);
    int queries[][2] = {{0, 8}, {0, 3}, {2, 4}, {6, 8}, {4, 4}};
    for (auto& q : queries)
        cout << "min a[" << q[0] << ".." << q[1] << "] = " << t.query(q[0], q[1]) << "\n";
    return 0;
}

#include <iostream>
#include <numeric>
#include <utility>
#include <vector>
using namespace std;

// Disjoint set union with path halving and union by size.
struct DSU {
    vector<int> parent, size;
    explicit DSU(int n) : parent(n), size(n, 1) { iota(parent.begin(), parent.end(), 0); }

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];  // skip a level on the way up
            x = parent[x];
        }
        return x;
    }

    bool unite(int a, int b) {  // false when a and b were already connected
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (size[a] < size[b]) swap(a, b);  // the smaller tree goes under the larger
        parent[b] = a;
        size[a] += size[b];
        return true;
    }
};

int main() {
    DSU d(8);
    int components = 8;
    vector<pair<int, int>> edges = {{0, 1}, {2, 3}, {1, 3}, {4, 5}, {3, 0}, {6, 7}, {5, 6}};
    for (const auto& [a, b] : edges) {
        if (d.unite(a, b)) {
            --components;
            cout << "join " << a << "-" << b << ": " << components << " components\n";
        } else {
            cout << "skip " << a << "-" << b << ": already connected, so this edge closes a cycle\n";
        }
    }
    cout << "0 and 2 connected? " << (d.find(0) == d.find(2) ? "yes" : "no") << "\n";
    cout << "0 and 4 connected? " << (d.find(0) == d.find(4) ? "yes" : "no") << "\n";
    return 0;
}
